import json
pts=[(0,3),(2,0),(4,-2),(7,0),(10,3)]
def area(a,b):
    s=0.0
    for (x1,y1),(x2,y2) in zip(pts,pts[1:]):
        lo=max(a,x1);hi=min(b,x2)
        if lo<hi:
            f=lambda t:y1+(y2-y1)*(t-x1)/(x2-x1)
            s+=(f(lo)+f(hi))/2*(hi-lo)
    return s
def H(x):
    return 20+(area(7,x) if x>=7 else -area(x,7))
opts=[0,2,7,10]
vals=[H(x) for x in opts]
print(json.dumps({"computed_key_index":vals.index(min(vals)),"conceptual_only":False,"details":str(vals)}))
